const dateField = (scope: ReturnType<Page['locator']>) => scope.getByRole('textbox', { name: 'תאריך אספקה' });
const hourField = (scope: ReturnType<Page['locator']>) => scope.getByLabel('שעת יעד לאספקה', { exact: true });

async function openBoard(page: Page, delivered = false) {
  await page.goto('/delivery');
  await expect(page.getByRole('heading', { level: 1, name: 'משלוחים' })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByRole('link', { name: /^תעודת משלוח · הזמנה #\d+/ }).first().or(page.getByRole('heading', { name: 'אין משלוחים פתוחים' }))).toBeVisible({ timeout: 30_000 });
  if (delivered) {
    await page.getByRole('button', { name: 'הצגת משלוחים שסופקו' }).click();
    await expect(page.getByRole('heading', { level: 2, name: /^סופקו/ })).toBeVisible({ timeout: 30_000 });
  }
}
const boardLink = (page: Page, no: string) => page.getByRole('link', { name: `תעודת משלוח · הזמנה #${no}`, exact: true });

async function openNote(page: Page, id: string, no: string) {
  await page.goto(`/delivery/${id}`);
  await expect(page.getByRole('heading', { level: 1, name: `תעודת משלוח · הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText(`ת. משלוח #DN-${no}`)).toBeVisible({ timeout: 30_000 });
}

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible({ timeout: 30_000 });
  const row = page.locator('div').filter({ hasText: employee }).filter({ has: page.getByRole('button', { name: 'פעולות' }) }).last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 30_000 });
}
async function backToAdmin(page: Page) {
  await page.getByRole('button', { name: 'חזרה לחשבון הניהול' }).click();
  await expect(page.getByText('מפיץ ראשי').first()).toBeVisible({ timeout: 30_000 });
}

/** Текст «דוח משלוחים» = печатная версия доски /delivery (кнопка «הורדת PDF»), строка заказа. */
async function reportRow(page: Page, no: string) {
  await page.emulateMedia({ media: 'print' });
  await expect(page.getByRole('heading', { name: 'דוח משלוחים' })).toBeVisible();
  const row = page.getByRole('row', { name: new RegExp(`^#${no}\\s`) });
  await expect(row).toBeVisible();
  const text = await row.innerText();
  await page.emulateMedia({ media: 'screen' });
  return text;
}

