test.describe('delivery — שעת הזמנה + שעת יעד על הזמנת QA-AUTO-delivery- (#599f82)', () => {
  test.describe.configure({ mode: 'serial' });

  const order: { no?: string; id?: string; before?: number; after?: number } = {};
  const customer: { original?: string; changed?: boolean } = {};
  const DELIVERY_ISO = isoDate(3); // после перехода на зимнее время (25.10.2026) — час не должен сдвигаться
  const DELIVERY = DELIVERY_ISO.split('-').reverse().join('.');
  const HOUR = '16:00';
  const HOUR2 = '17:45';

  test.beforeAll(async ({ browser }) => {
    test.setTimeout(180_000);
    customer.original = await customerAddress(browser, null);
    if (!customer.original.trim()) { await customerAddress(browser, TEMP_ADDRESS); customer.changed = true; }
    Object.assign(order, await buyerPlaceOrder(browser, `QA-AUTO-delivery-hour-${Date.now()}`));
  });

  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    try {
      await finishOrder(browser, order);
    } finally {
      if (customer.changed) await customerAddress(browser, customer.original ?? '');
    }
  });

  test('שעת ההזמנה נשמרת אוטומטית: אצל הלקוח (רשימה + פרטים) ואצל מפיץ — השעה של רגע השליחה #599f82 @desktop @data', async ({ asUser }) => {
    const buyer = await asUser('buyer');
    await buyer.goto('/shop/orders');
    const row = buyer.getByRole('link', { name: new RegExp(`^הזמנה #${order.no}\\b`) });
    await expect(row).toBeVisible({ timeout: 30_000 });
    const shown = parseBuyerDate(await row.innerText());
    // ожидаемое — момент отправки в часовом поясе этого же окна (с запасом: от минуты до отправки до минуты после)
    const range = await buyer.evaluate(([b, a]) => {
      const f = (t: number) => {
        const d = new Date(t);
        const p = (x: number) => String(x).padStart(2, '0');
        return { date: `${p(d.getDate())}.${p(d.getMonth() + 1)}.${d.getFullYear()}`, min: d.getHours() * 60 + d.getMinutes() };
      };
      return [f(b), f(a)];
    }, [order.before!, order.after!]);
    const [hh, mm] = shown.time.split(':').map(Number);
    expect([range[0].date, range[1].date], 'дата заказа = сегодня').toContain(shown.date);
    expect(hh * 60 + mm, `время заказа ${shown.time} = моменту отправки`).toBeGreaterThanOrEqual(range[0].min);
    expect(hh * 60 + mm, `время заказа ${shown.time} = моменту отправки`).toBeLessThanOrEqual(range[1].min);

    await row.click();
    await expect(buyer.getByRole('heading', { level: 1, name: `הזמנה #${order.no}` })).toBeVisible({ timeout: 30_000 });
    expect(parseBuyerDate(await buyer.locator('body').innerText()), 'детали — то же время').toEqual(shown);

    const admin = await asUser('admin');
    await admin.goto(`/orders/${order.id}`);
    await expect(admin.getByRole('heading', { level: 1, name: `הזמנה #${order.no}` })).toBeVisible({ timeout: 30_000 });
    await expect(admin.getByText(`${shown.date}, ${shown.time}`, { exact: true }).first(), 'מפיץ: DD.MM.YYYY, HH:MM').toBeVisible();
  });

  test(`שיוך מכרטיס ההזמנה: ${DRIVER} + תאריך + «שעת יעד לאספקה» ${HOUR} נשמרים; בלוח «אספקה: עד … בשעה …», בתעודה ובהדפסה, ב«דוח משלוחים» #599f82 @desktop @data`, async ({ page }) => {
    await openOrder(page, order);
    const card = shipCard(page);
    await page.getByRole('button', { name: 'אישור הזמנה' }).click();
    await page.getByRole('dialog').getByRole('button', { name: 'אשר הזמנה' }).click();
    await expect(card).toContainText('ממתינה לליקוט', { timeout: 30_000 });
    await expect(card.getByText('ללקוח אין כתובת משלוח')).toHaveCount(0);

    await card.getByRole('combobox', { name: 'נהג' }).selectOption({ label: DRIVER });
    await expect(hourField(card)).toBeDisabled();
    await dateField(card).fill(DELIVERY_ISO);
    await expect(hourField(card)).toBeEnabled();
    await hourField(card).fill(HOUR);
    await card.getByRole('button', { name: 'שמירת שיבוץ' }).click();
    await expect(page.getByText('השיבוץ נשמר')).toBeVisible({ timeout: 30_000 });
    await page.reload();
    await expect(dateField(shipCard(page))).toHaveValue(DELIVERY_ISO, { timeout: 30_000 });
    await expect(hourField(shipCard(page)), 'час сохранён, не сдвинут').toHaveValue(HOUR);

    const ready = shipCard(page).getByRole('button', { name: /^סמן כמוכנה? למשלוח$/ });
    await ready.click();
    await expect(ready).toHaveCount(0, { timeout: 30_000 });
    await expect(shipCard(page)).toContainText('ההזמנה ארוזה וממתינה ליציאת הנהג', { timeout: 30_000 });

    await openBoard(page);
    await expect(boardLink(page, order.no!).locator('..')).toContainText(`אספקה: עד ${DELIVERY} בשעה ${HOUR}`);
    expect(await reportRow(page, order.no!), '«דוח משלוחים»').toMatch(new RegExp(`${DELIVERY.replace(/\./g, '\\.')}\\s*עד ${HOUR}`));

    await openNote(page, order.id!, order.no!);
    expect(await page.locator('main').innerText()).toContain(`תאריך אספקה: ${DELIVERY}\nשעת יעד לאספקה: עד ${HOUR}`);
    await page.emulateMedia({ media: 'print' });
    await expect(page.getByText('פריטי המשלוח')).toBeVisible();
    expect(await page.evaluate(() => document.body.innerText), 'печать תעודה').toMatch(new RegExp(`שעת יעד לאספקה:\\s*עד ${HOUR}`));
    await page.emulateMedia({ media: 'screen' });
  });

  test(`נהג רואה «אספקה: עד DD.MM.YYYY בשעה ${HOUR}» ברשימה ובתעודה #599f82 @desktop @data`, async ({ page }) => {
    await impersonate(page, DRIVER);
    try {
      await openBoard(page);
      const link = boardLink(page, order.no!);
      await expect(link.locator('..')).toContainText(`אספקה: עד ${DELIVERY} בשעה ${HOUR}`);
      await link.click();
      await expect(page.getByText(`ת. משלוח #DN-${order.no}`)).toBeVisible({ timeout: 30_000 });
      expect(await page.locator('main').innerText()).toContain(`תאריך אספקה: ${DELIVERY}\nשעת יעד לאספקה: עד ${HOUR}`);
    } finally {
      await backToAdmin(page);
    }
  });

  test(`מפיץ משנה את השעה בתעודה («שייך ושלח לנהג») ל-${HOUR2} — נשמר, הלוח מתעדכן #599f82 @desktop @data`, async ({ page }) => {
    await openNote(page, order.id!, order.no!);
    const panel = notePanel(page);
    await expect(hourField(panel)).toHaveValue(HOUR, { timeout: 30_000 });
    await panel.getByRole('combobox', { name: 'נהג' }).selectOption({ label: DRIVER });
    await hourField(panel).fill(HOUR2);
    await Promise.all([
      page.waitForResponse((r) => r.request().method() !== 'GET' && r.url().includes('supabase') && r.ok(), { timeout: 30_000 }),
      panel.getByRole('button', { name: 'שייך ושלח לנהג' }).click(),
    ]);
    await page.reload();
    await expect(page.getByText(`ת. משלוח #DN-${order.no}`)).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(`שעת יעד לאספקה: עד ${HOUR2}`)).toBeVisible();
    await expect(page.getByText(`נהג: ${DRIVER}`)).toBeVisible();
    await openBoard(page);
    await expect(boardLink(page, order.no!).locator('..')).toContainText(`אספקה: עד ${DELIVERY} בשעה ${HOUR2}`);
  });
});

// ---------------------------------------------------------------- helpers (данные)
function isoDate(daysAhead: number) {
  return new Date(Date.now() + daysAhead * 86_400_000).toISOString().slice(0, 10);
}

/** Читает «כתובת מלאה» клиента «test»; value !== null — записывает его. Возвращает значение до записи. */
async function customerAddress(browser: Browser, value: string | null): Promise<string> {
  const ctx = await browser.newContext({ storageState: auth('admin') });
  const page = await ctx.newPage();
  try {
    await page.goto(`${CUSTOMER_PATH}/edit`);
    await expect(page.getByRole('heading', { level: 1, name: 'עריכת לקוח' })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByRole('textbox', { name: /^שם עסק/ })).not.toHaveValue('', { timeout: 30_000 });
    const field = page.getByRole('textbox', { name: 'כתובת מלאה' });
    const before = await field.inputValue();
    if (value !== null && before !== value) {
      await field.fill(value);
      await page.getByRole('button', { name: 'שמירה', exact: true }).click();
      await expect(page).toHaveURL(/\/customers$/, { timeout: 30_000 });
      await page.goto(`${CUSTOMER_PATH}/edit`);
      await expect(page.getByRole('textbox', { name: 'כתובת מלאה' })).toHaveValue(value, { timeout: 30_000 });
    }
    return before;
  } finally {
    await ctx.close();
  }
}

async function buyerPlaceOrder(browser: Browser, note: string) {
  const ctx = await browser.newContext({ storageState: auth('buyer') });
  const page = await ctx.newPage();
  try {
    await page.goto('/shop/cart');
    await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible({ timeout: 30_000 });
    const remove = page.getByRole('button', { name: /^הסרה מהעגלה/ });
    await expect(remove.first().or(page.getByText('העגלה ריקה'))).toBeVisible({ timeout: 30_000 });
    for (let n = await remove.count(); n > 0; n--) {
      await remove.first().click();
      await expect(remove).toHaveCount(n - 1, { timeout: 15_000 });
    }
    await page.goto(`/shop/p/${ITEM.id}`);
    await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
    await expect(async () => {
      await page.goto('/shop/cart');
      await expect(page.getByText(ITEM.name, { exact: true })).toBeVisible({ timeout: 3_000 });
    }).toPass({ timeout: 30_000 });
    await page.getByRole('button', { name: 'המשך לביצוע הזמנה' }).click();
    await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill(note);
    const before = Date.now() - 60_000; // минута запаса: время на сервере округляется вниз до минуты
    await page.getByRole('button', { name: 'שליחת הזמנה' }).click();
    await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toBeVisible({ timeout: 30_000 });
    const after = Date.now() + 60_000;
    const no = (await page.getByText(/^#\d+$/).first().innerText()).match(/#(\d+)/)![1];
    await page.goto('/shop/orders');
    const row = page.getByRole('link', { name: new RegExp(`^הזמנה #${no}\\b`) });
    await expect(row).toBeVisible({ timeout: 30_000 });
    const id = (await row.getAttribute('href'))!.split('/').pop()!;
    return { no, id, before, after };
  } finally {
    await ctx.close();
  }
}

async function openOrder(page: Page, order: { no?: string; id?: string }) {
  await page.goto(`/orders/${order.id}`);
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${order.no}` })).toBeVisible({ timeout: 30_000 });
  await expect(shipCard(page)).toBeVisible({ timeout: 30_000 });
}

async function finishOrder(browser: Browser, o: { no?: string; id?: string }) {
  // доводим заказ QA-AUTO до конечного статуса — тем же порядком, что delivery-lifecycle.spec.ts
  const ctx = await browser.newContext({ storageState: auth('admin') });
  const page = await ctx.newPage();
  try {
    if (!o.no || !o.id) return;
    await openOrder(page, o);
    if (await page.getByRole('button', { name: 'דחייה' }).count()) {
      await page.getByRole('button', { name: 'דחייה' }).click();
      await page.getByRole('dialog').getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO cleanup');
      await page.getByRole('dialog').getByRole('button', { name: 'דחה הזמנה' }).click();
      return;
    }
    for (const b of [/^סמן כמוכנה? למשלוח$/, /^סמן כיצאה? למשלוח$/, /^סמן כסופקה?$/]) {
      const btn = shipCard(page).getByRole('button', { name: b });
      if ((await btn.count()) && (await btn.isEnabled())) { await btn.click(); await expect(btn).toHaveCount(0, { timeout: 30_000 }); }
    }
    if (!(await shipCard(page).getByText(/^סופקה?$/).count())) {
      // при назначенном водителе «יצאה למשלוח» / «סופקה» отмечает водитель
      await impersonate(page, DRIVER);
      await openBoard(page);
      await boardLink(page, o.no!).click();
      await expect(page.getByText(`ת. משלוח #DN-${o.no}`)).toBeVisible({ timeout: 30_000 });
      const out = page.getByRole('button', { name: /יצאה? למשלוח/ });
      if (await out.count()) { await out.click(); await expect(out).toHaveCount(0, { timeout: 30_000 }); }
      const done = page.getByRole('button', { name: /כסופקה?/ });
      if (await done.count()) { await done.click(); await expect(done).toHaveCount(0, { timeout: 30_000 }); }
      await backToAdmin(page);
      await openOrder(page, o);
    }
    await expect(shipCard(page).getByText(/^סופקה?$/).first()).toBeVisible({ timeout: 30_000 });
  } finally {
    await ctx.close();
  }
}
